class BigNumCalculator:
    BASE = 10

    @staticmethod
    def _add_digits(num1: str, num2: str) -> str:
        carry = 0
        result = []
        for i in range(len(num1) - 1, -1, -1):
            digit_sum = int(num1[i]) + int(num2[i]) + carry
            carry = digit_sum // BigNumCalculator.BASE
            digit = digit_sum % BigNumCalculator.BASE
            result.insert(0, str(digit))

        if carry > 0:
            result.insert(0, str(carry))

        return ''.join(result)

    @staticmethod
    def _subtract_digits(num1: str, num2: str) -> str:
        borrow = 0
        result = []
        for i in range(len(num1) - 1, -1, -1):
            digit_diff = int(num1[i]) - int(num2[i]) - borrow

            if digit_diff < 0:
                digit_diff += BigNumCalculator.BASE
                borrow = 1
            else:
                borrow = 0

            result.insert(0, str(digit_diff))

        while len(result) > 1 and result[0] == '0':
            result.pop(0)

        return ''.join(result)

    @staticmethod
    def _determine_order(num1: str, num2: str):
        if len(num1) < len(num2):
            return num2, num1, True
        elif len(num1) > len(num2):
            return num1, num2, False
        else:
            if num1 < num2:
                return num2, num1, True
            else:
                return num1, num2, False

    @staticmethod
    def _strip_leading_zeros(digits) -> str:
        start = 0
        while start < len(digits) - 1 and digits[start] == 0:
            start += 1

        return ''.join(map(str, digits[start:]))

    @staticmethod
    def add(num1, num2):
        max_length = max(len(num1), len(num2))
        padded_num1 = num1.zfill(max_length)
        padded_num2 = num2.zfill(max_length)

        return BigNumCalculator._add_digits(padded_num1, padded_num2)

    @staticmethod
    def subtract(num1, num2):
        larger_num, smaller_num, negative = BigNumCalculator._determine_order(num1, num2)

        max_length = max(len(larger_num), len(smaller_num))
        padded_larger = larger_num.zfill(max_length)
        padded_smaller = smaller_num.zfill(max_length)

        result_digits = BigNumCalculator._subtract_digits(padded_larger, padded_smaller)

        if negative:
            f"-{result_digits}"

        return result_digits

    @staticmethod
    def multiply(num1, num2):
        len1 = len(num1)
        len2 = len(num2)
        result = [0] * (len1 + len2)

        for i in range(len1 - 1, -1, -1):
            for j in range(len2 - 1, -1, -1):
                mul = int(num1[i]) * int(num2[j])
                p1, p2 = i + j, i + j + 1
                total = mul + result[p2]

                result[p1] += total // BigNumCalculator.BASE
                result[p2] = total % BigNumCalculator.BASE

        return BigNumCalculator._strip_leading_zeros(result)
